# Three service benefits
f1, f2, f3 = st.columns(3)
with f1:
    st.markdown('<div class="rx-feature"><div class="rx-feature-icon">🚚</div><div class="rx-feature-title">Easy pickup</div><div class="rx-feature-copy">Book collection in minutes</div></div>', unsafe_allow_html=True)
with f2:
    st.markdown('<div class="rx-feature"><div class="rx-feature-icon">📍</div><div class="rx-feature-title">Location aware</div><div class="rx-feature-copy">Share your pickup location</div></div>', unsafe_allow_html=True)
with f3:
    st.markdown('<div class="rx-feature"><div class="rx-feature-icon">🌱</div><div class="rx-feature-title">Responsible</div><div class="rx-feature-copy">Choose a cleaner tomorrow</div></div>', unsafe_allow_html=True)

st.write("")

# Create a separate Supabase client for this browser session.
# Keep customer sessions isolated; do not share authenticated clients.
supabase = create_client(
    st.secrets["SUPABASE_URL"],
    st.secrets["SUPABASE_KEY"]
)

# Restore this customer's login session.
if st.session_state.get("access_token"):
    try:
        supabase.auth.set_session(
            st.session_state["access_token"],
            st.session_state["refresh_token"]
        )
    except Exception:
        for key in [
            "access_token", "refresh_token",
            "customer_id", "customer_name", "customer_phone"
        ]:
            st.session_state.pop(key, None)

# ---------------------------------
# LOGIN AND REGISTRATION
# ---------------------------------
if not st.session_state.get("access_token"):
    st.markdown("""
    <div class="rx-auth-intro">
      <div class="rx-auth-kicker">Welcome to a greener way</div>
      <div class="rx-auth-title">Your next step starts here.</div>
      <div class="rx-auth-copy">Sign in or create an account to arrange your e-waste pickup.</div>
    </div>
    """, unsafe_allow_html=True)
    menu = st.radio(
        "Choose how to continue",
        ["Login", "Register"],
        horizontal=True,
        key="auth_menu",
        label_visibility="collapsed"
    )

    if menu == "Register":
        st.markdown('<div class="rx-auth-intro"><div class="rx-auth-title">Create your account</div><div class="rx-auth-copy">Join RecycleX and make responsible recycling easier.</div></div>', unsafe_allow_html=True)

        with st.form("register_form"):
            name = st.text_input("Full Name")
            phone = st.text_input("Mobile Number")
            email = st.text_input("Email Address")
            password = st.text_input("Create Password", type="password")
            submit = st.form_submit_button("Create Account")

            if submit:
                if not all([name.strip(), phone.strip(), email.strip(), password]):
                    st.error("Please complete all fields.")
                elif len(password) < 8:
                    st.error("Password must be at least 8 characters.")
                else:
                    try:
                        supabase.auth.sign_up({
                            "email": email.strip(),
                            "password": password,
                            "options": {
                                "data": {
                                    "full_name": name.strip(),
                                    "phone": phone.strip()
                                }
                            }
                        })
                        st.success(
                            "Registration submitted. Confirm your email if requested, then log in."
                        )
                    except Exception:
                        st.error("Registration failed. Please check your details and try again.")

    else:
        st.markdown('<div class="rx-auth-intro"><div class="rx-auth-title">Welcome back 👋</div><div class="rx-auth-copy">Log in to book a pickup and manage your requests.</div></div>', unsafe_allow_html=True)

        with st.form("login_form"):
            email = st.text_input("Email Address")
            password = st.text_input("Password", type="password")
            submit = st.form_submit_button("Login")

            if submit:
                try:
                    response = supabase.auth.sign_in_with_password({
                        "email": email.strip(),
                        "password": password
                    })

                    session = response.session
                    user = response.user

                    st.session_state["access_token"] = session.access_token
                    st.session_state["refresh_token"] = session.refresh_token
                    st.session_state["customer_id"] = str(user.id)

                    metadata = user.user_metadata or {}
                    st.session_state["customer_name"] = metadata.get("full_name", "")
                    st.session_state["customer_phone"] = metadata.get("phone", "")

                    st.rerun()
                except Exception:
                    st.error("Login failed. Please check your email and password.")

    st.markdown('<div class="rx-auth-note"><span>🔒</span> Your account details are handled securely.</div>', unsafe_allow_html=True)

# ---------------------------------
# CUSTOMER DASHBOARD
# ---------------------------------
else:
    customer_id = st.session_state["customer_id"]
    customer_name = st.session_state.get("customer_name") or "Customer"

    st.markdown(f'''<div class="rx-dashboard-hero"><div class="small">YOUR RECYCLEX SPACE</div><div class="big">Welcome, {customer_name} 👋</div><div class="copy">Ready to give your old appliances a responsible next life?</div></div>''', unsafe_allow_html=True)
    st.markdown('<div class="rx-section-label">Pickup service · Kolkata</div>', unsafe_allow_html=True)

    page = st.radio(
        "Your RecycleX dashboard",
        ["Book a Pickup", "My Bookings"],
        horizontal=True,
        key="customer_menu"
    )

    if page == "Book a Pickup":
        st.header("Schedule a pickup")
        st.caption("Tell us what you want collected and where we should come.")

        # RecycleX appliance image gallery
        product_images = {
            "Fridge": "",
            "Air Conditioner": "",
            "Fan": "",
            "Mixer Grinder": "",
            "Other Appliances": "",
            "Other E-Waste": "",
        }
        gallery_html = '<div class="rx-product-grid">'
        for product_name, encoded_image in product_images.items():
            gallery_html += (
                '<div class="rx-product-card">'
                f'<img src="data:image/jpeg;base64,{encoded_image}" alt="{product_name}">'
                f'<div>{product_name}</div>'
                '</div>'
            )
        gallery_html += '</div>'
        st.markdown(gallery_html, unsafe_allow_html=True)

        st.subheader("Choose your appliances")
        selected_products = st.multiselect(
            "Select all products for this pickup",
            [
                "Fridge", "Air Conditioner", "Fan", "Mixer Grinder",
                "Other Appliances", "Other E-Waste"
            ],
            key="selected_pickup_products",
            placeholder="Choose one or more products"
        )

        product_quantities = {}
        if selected_products:
            st.caption("Enter the quantity for each selected product.")
            quantity_columns = st.columns(2)
            for index, product_name in enumerate(selected_products):
                with quantity_columns[index % 2]:
                    product_quantities[product_name] = st.number_input(
                        f"{product_name} quantity",
                        min_value=1,
                        value=1,
                        step=1,
                        key=f"quantity_{product_name.replace(' ', '_').lower()}"
                    )

        with st.form("pickup_booking_form"):
            name = st.text_input(
                "Full Name",
                value=st.session_state.get("customer_name", "")
            )
            phone = st.text_input(
                "Mobile Number",
                value=st.session_state.get("customer_phone", "")
            )
            address = st.text_area("Complete Pickup Address")

            st.subheader("Pickup GPS Location")
            location = streamlit_geolocation()

            latitude = None
            longitude = None

            if location and location.get("latitude") is not None:
                latitude = location["latitude"]
                longitude = location["longitude"]
                st.success("GPS location detected successfully!")
                st.write("Latitude:", latitude)
                st.write("Longitude:", longitude)
                map_data = pd.DataFrame({
                    "latitude": [latitude],
                    "longitude": [longitude]
                })
                st.map(map_data)
            else:
                st.info(
                    "Allow location access in your browser to detect your pickup location. "
                    "You can still enter your address manually."
                )

            st.text_input("Service City", value="Kolkata", disabled=True)

            weight = st.number_input(
                "Estimated Weight (kg)",
                min_value=0.0,
                value=1.0,
                step=0.5
            )
            pickup_date = st.date_input(
                "Preferred Pickup Date",
                min_value=date.today()
            )
            pickup_time = st.selectbox(
                "Preferred Pickup Time",
                ["Morning", "Afternoon", "Evening"]
            )
            notes = st.text_area("Additional Information (Optional)")

            submit = st.form_submit_button("Submit Pickup Request")

            if submit:
                if not name.strip() or not phone.strip() or not address.strip():
                    st.error("Please enter your name, mobile number and complete pickup address.")
                elif not selected_products:
                    st.error("Please select at least one appliance.")
                else:
                    try:
                        category = ", ".join(
                            f"{product}: {int(product_quantities[product])}"
                            for product in selected_products
                        )
                        supabase.table("customer_bookings").insert({
                            "customer_user_id": customer_id,
                            "customer_name": name.strip(),
                            "customer_phone": phone.strip(),
                            "pickup_address": address.strip(),
                            "city": "Kolkata",
                            "latitude": latitude,
                            "longitude": longitude,
                            "e_waste_category": category,
                            "estimated_weight": weight,
                            "preferred_pickup_date": pickup_date.isoformat(),
                            "preferred_pickup_time": pickup_time,
                            "customer_notes": notes.strip()
                        }).execute()

                        st.session_state["customer_name"] = name.strip()
                        st.session_state["customer_phone"] = phone.strip()
                        st.success("Your pickup request has been submitted!")
                    except Exception:
                        st.error("Unable to submit pickup request. Please try again or contact support.")

    elif page == "My Bookings":
        st.header("My pickup requests")
        st.caption("View the latest requests submitted from your account.")

        try:
            response = supabase.table("customer_bookings").select(
                "id, e_waste_category, estimated_weight, "
                "preferred_pickup_date, preferred_pickup_time, "
                "booking_status, created_at"
            ).eq(
                "customer_user_id", customer_id
            ).order(
                "created_at", desc=True
            ).execute()

            if response.data:
                bookings_df = pd.DataFrame(response.data)
                st.dataframe(bookings_df, use_container_width=True, hide_index=True)
            else:
                st.info("You have not submitted any pickup requests yet.")
        except Exception:
            st.error("Unable to load your bookings. Please try again.")

    st.divider()
    if st.button("Logout"):
        for key in [
            "access_token", "refresh_token", "customer_id",
            "customer_name", "customer_phone"
        ]:
            st.session_state.pop(key, None)
        st.rerun()

st.markdown(
    '<div class="rx-footer">RecycleX · Powered by Lokesh Seth E Waster Manager</div>',
    unsafe_allow_html=True
)
